    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            upper = grid[:r]
            lower = grid[r + 1:]
            return [
                [2 if a != 0 and b != 0 else 0 for a, b in zip(row_a, row_b)]
                for row_a, row_b in zip(upper, lower)
            ]

    for c in range(w):
        if all(grid[r][c] == grid[0][c] != 0 for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            return [
                [2 if a != 0 and b != 0 else 0 for a, b in zip(row_a, row_b)]
                for row_a, row_b in zip(left, right)
            ]

